import{at as e,it as t,t as n,yt as r}from"./chunks/framework.CgPcrqpH.js";var i=JSON.parse(`{"title":"Publish a Blog Post","description":"","frontmatter":{},"headers":[],"relativePath":"skills/contributors/publish-a-blog-post.md","filePath":"skills/contributors/publish-a-blog-post.md"}`),a={name:`skills/contributors/publish-a-blog-post.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="publish-a-blog-post" tabindex="-1">Publish a Blog Post <a class="header-anchor" href="#publish-a-blog-post" aria-label="Permalink to “Publish a Blog Post”">​</a></h1><p>Use this skill whenever you&#39;re adding a post under the repo-root <code>blog/</code> directory, starting a new major-version section of it, or retiring a post that&#39;s out of date. The blog holds release announcements and other point-in-time posts. Release posts are dual-published here from <a href="https://blog.emberjs.com/" target="_blank" rel="noreferrer">blog.emberjs.com</a> so that consumers who don&#39;t use Ember don&#39;t have to go looking for them there. Every post&#39;s URL is a permanent contract with readers, so most of the rules below exist to keep a post&#39;s path, date and version from ever changing under them.</p><p>For drafting the prose itself, follow <a href="./write-documentation">Write Documentation</a> as well; this skill covers where a post goes and how it gets listed. If the post announces a release, start from <a href="./draft-a-release-blog-post">Draft a Release Blog Post</a>, which gathers its content and says when it has to merge.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to “Steps”">​</a></h2><ol><li>Read <a href="/pr-preview/pr-9539/guides/contributing/writing-documentation/writing-guides#upgrading-and-blog-pages">Upgrading and Blog Pages</a> before writing anything. It owns the rules this skill relies on: URLs are never renamed or unpublished, every post is dated and versioned, and posts are organized by major version.</li><li>Put the post at <code>blog/v&lt;major&gt;/&lt;slug&gt;.md</code>, where <code>&lt;major&gt;</code> is the major version that was current when the post is published. Pick the slug as if it can never change, because it can&#39;t: the URL is also the post&#39;s ID in the RSS feed, so renaming it later shows every subscriber the post again as new.</li><li>If <code>blog/v&lt;major&gt;/</code> doesn&#39;t exist yet, create it with: <ul><li>an <code>index.md</code> whose frontmatter has a <code>title</code> (<code>&lt;major&gt;.x</code>) and a <code>description</code>, an H1, one sentence of intro, and <code>&lt;BlogPostList version=&quot;&lt;major&gt;&quot; /&gt;</code>, copying <code>blog/v5/index.md</code>;</li><li>a <code>_meta.json</code> with the section&#39;s <code>title</code> and <code>items: [&quot;index&quot;]</code>;</li><li>the directory added to <code>items</code> in <code>blog/_meta.json</code>, so sections sort in release order, and a link to the new section added to the &quot;browse posts by major version&quot; sentence in <code>blog/index.md</code>.</li></ul></li><li>Give the post frontmatter <code>title</code>, <code>description</code>, and <code>date</code> (<code>YYYY-MM-DD</code>, the publish date), and put the <code>&lt;SinceBadge&gt;</code> and date line under the H1, as the guide in step 1 shows. Copy an existing post such as <code>blog/v5/introducing-upgrading-and-blog.md</code> for the shape. The docs build fails on a post without a valid <code>date</code>.</li><li>Add the post&#39;s slug to <code>items</code> in its directory&#39;s <code>_meta.json</code>, after the posts already there. That only orders the sidebar.</li><li>Don&#39;t add the post to any list by hand. <code>/blog/</code>, each <code>/blog/v&lt;major&gt;/</code> page and <code>/blog/feed.xml</code> are all generated from post frontmatter by <code>blogPosts</code> in <code>docs-viewer/src/site-utils.ts</code>, so a post appears in all three, newest first by <code>date</code>, as soon as it exists and isn&#39;t a draft. If a post is missing from them, fix its frontmatter, not the listing.</li><li>To retire a post, follow <a href="/pr-preview/pr-9539/guides/contributing/writing-documentation/writing-guides#urls-are-never-renamed-or-unpublished">URLs are never renamed or unpublished</a>. Its <code>draft: true</code> also takes it out of the listings and the feed, while its URL keeps working.</li><li>Run <code>pnpm lint:docs</code> from the repo root, then build the site as <a href="/pr-preview/pr-9539/guides/contributing/writing-documentation/#previewing-your-changes">Previewing Your Changes</a> describes and check the post&#39;s page, <code>/blog/</code> and <code>/blog/feed.xml</code>. A post added while <code>pnpm start</code> is running needs a restart before it shows up in the sidebar.</li></ol>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};